import crypto from 'crypto';
import db from '../config/db.js';

// Long-lived credential for the LIS-Agent Electron app — one per physical
// machine, generated by an Admin and pasted into the app's activation
// screen once at install. Deliberately NOT a JWT: it has no expiry, so an
// unattended lab PC never gets logged out mid-shift the way a normal staff
// session would. It carries Lab Technician-level access (see
// middleware/auth.js authenticateToken's device-key branch), same as if a
// tech were logged in on that machine — so treat generating one with the
// same care as handing out a lab tech's password, and revoke immediately if
// a machine is lost or decommissioned.
const hashKey = (key) => crypto.createHash('sha256').update(key).digest('hex');

export const createDeviceKey = async (req, res) => {
  try {
    const { label, branch_id } = req.body;
    if (!label || !String(label).trim()) {
      return res.status(400).json({ success: false, message: 'A label (e.g. machine name) is required.' });
    }

    // 32 random bytes, base64url — short enough to paste comfortably, long
    // enough that guessing is not a realistic attack.
    const plainKey = crypto.randomBytes(32).toString('base64url');
    const keyHash = hashKey(plainKey);

    const [result] = await db.query(
      `INSERT INTO device_api_keys (key_hash, label, branch_id, created_by)
       VALUES (?, ?, ?, ?)`,
      [keyHash, String(label).trim(), branch_id || req.user?.branch_id || null, req.user?.id || null]
    );

    // The plaintext key is returned exactly once, here — only the hash is
    // ever stored, so if this response is missed there is no "forgot my
    // key" recovery; a new key has to be generated and the old one revoked.
    res.status(201).json({
      success: true,
      message: 'Device key created. Copy it now — it will not be shown again.',
      device_key: {
        id: result.insertId,
        label: String(label).trim(),
        key: plainKey,
      },
    });
  } catch (error) {
    console.error('Error creating device key:', error);
    res.status(500).json({ success: false, message: 'Server error creating device key' });
  }
};

export const listDeviceKeys = async (req, res) => {
  try {
    const [rows] = await db.query(
      `SELECT dk.id, dk.label, dk.branch_id, br.branch_name, dk.status,
              dk.last_used_at, dk.last_used_ip, dk.created_at, dk.revoked_at,
              CONCAT(u.first_name, ' ', u.last_name) AS created_by_name
       FROM device_api_keys dk
       LEFT JOIN branches br ON br.id = dk.branch_id
       LEFT JOIN users u ON u.id = dk.created_by
       ORDER BY dk.created_at DESC`
    );
    res.json({ success: true, device_keys: rows });
  } catch (error) {
    console.error('Error listing device keys:', error);
    res.status(500).json({ success: false, message: 'Server error listing device keys' });
  }
};

export const revokeDeviceKey = async (req, res) => {
  try {
    const { id } = req.params;
    const [result] = await db.query(
      `UPDATE device_api_keys SET status = 'Revoked', revoked_at = NOW()
       WHERE id = ? AND status = 'Active'`,
      [id]
    );
    if (result.affectedRows === 0) {
      return res.status(404).json({ success: false, message: 'Key not found or already revoked.' });
    }
    res.json({ success: true, message: 'Device key revoked — that machine will need a new key to reconnect.' });
  } catch (error) {
    console.error('Error revoking device key:', error);
    res.status(500).json({ success: false, message: 'Server error revoking device key' });
  }
};

// Lets the Electron activation screen confirm a pasted key is valid before
// storing it locally, with a clear error rather than only finding out on
// the first real API call later.
export const verifyDeviceKey = async (req, res) => {
  try {
    const { key } = req.body;
    if (!key) return res.status(400).json({ success: false, message: 'No key provided.' });

    const [[row]] = await db.query(
      `SELECT id, label, branch_id, role, status FROM device_api_keys WHERE key_hash = ? LIMIT 1`,
      [hashKey(key)]
    );
    if (!row || row.status !== 'Active') {
      return res.status(401).json({ success: false, message: 'Invalid or revoked device key.' });
    }
    // branch_id/role are handed back so the activation screen can seed the
    // same localStorage fields the old email/password Login used to set
    // (labId, role, branch_id) — every page downstream that reads those for
    // scoping keeps working unmodified.
    res.json({ success: true, label: row.label, branch_id: row.branch_id, role: row.role });
  } catch (error) {
    console.error('Error verifying device key:', error);
    res.status(500).json({ success: false, message: 'Server error verifying device key' });
  }
};

export { hashKey };
